const p = $input.first().json.body || $input.first().json;
return { json: {
  userId: p.userId, sessionId: p.sessionId, source: p.source,
  message: p.message || p.enrichedMessage || '', originalMessage: p.originalMessage || p.message || '',
  persona: typeof p.persona === 'string' ? JSON.parse(p.persona) : (p.persona || {}),
  replyTarget: p.replyTarget, replyToken: p.replyToken,
  timestamp: p.timestamp || new Date().toISOString(),
  databaseUrl: p.databaseUrl || process.env.DATABASE_URL || '',
  targetAgent: p.targetAgent, _dispatch_mode: p._dispatch_mode,
  _router_version: p._router_version, isBackground: p.isBackground || false, hasCrisis: p.hasCrisis || false
}};

// Load Credentials v5 — Explorer (Gemini Flash + embeddings)
const prev = $('Extract Payload').first().json;
const p = prev.persona || {};
const t = p.tokens || {};
const lang = p.language_preference || 'th';

const i18nMap = {
  th: { not_connected:'ยังไม่ได้เชื่อมต่อ', configure:'กรุณาตั้งค่าที่ /dashboard/api-settings', success:'สำเร็จ', error:'เกิดข้อผิดพลาด', completed:'เสร็จแล้ว', query_required:'กรุณาระบุคำค้นหา', url_required:'กรุณาระบุ URL', city_required:'กรุณาระบุชื่อเมือง', repo_required:'กรุณาระบุ repo (เช่น user/repo)', package_required:'กรุณาระบุชื่อแพ็กเกจ', github_username_missing:'ยังไม่ได้ตั้งค่า github_username ใน persona' },
  en: { not_connected:'Not connected', configure:'Please configure at /dashboard/api-settings', success:'Success', error:'Error occurred', completed:'Completed', query_required:'query is required', url_required:'url is required', city_required:'city is required', repo_required:'repo required (e.g. user/repo)', package_required:'package name is required', github_username_missing:'github_username not set in persona' },
  ja: { not_connected:'接続されていません', configure:'/dashboard/api-settingsで設定してください', success:'成功しました', error:'エラーが発生しました', completed:'完了しました', query_required:'検索クエリが必要です', url_required:'URLが必要です', city_required:'都市名が必要です', repo_required:'リポジトリが必要です', package_required:'パッケージ名が必要です', github_username_missing:'personaにgithub_usernameが設定されていません' },
  zh: { not_connected:'未连接', configure:'请在 /dashboard/api-settings 配置', success:'成功', error:'发生错误', completed:'已完成', query_required:'需要查询关键词', url_required:'需要URL', city_required:'需要城市名称', repo_required:'需要仓库名', package_required:'需要包名', github_username_missing:'persona中未设置github_username' }
};
const i18n = i18nMap[lang] || i18nMap['en'];

const get = (envKey, payloadKey) => t[payloadKey] || p[payloadKey] || process.env[envKey] || '';

const creds = {
  google_access_token:    get('GOOGLE_ACCESS_TOKEN','google_access_token'),
  google_refresh_token:   get('GOOGLE_REFRESH_TOKEN','google_refresh_token'),
  microsoft_access_token: get('MICROSOFT_ACCESS_TOKEN','microsoft_access_token'),
  outlook_access_token:   get('MICROSOFT_ACCESS_TOKEN','microsoft_access_token'),
  telegram_bot_token:     get('TELEGRAM_BOT_TOKEN','telegram_bot_token'),
  discord_bot_token:      get('DISCORD_BOT_TOKEN','discord_bot_token'),
  slack_bot_token:        get('SLACK_BOT_TOKEN','slack_bot_token'),
  twitter_bearer_token:   get('TWITTER_BEARER_TOKEN','twitter_bearer_token'),
  facebook_access_token:  get('FACEBOOK_ACCESS_TOKEN','facebook_access_token'),
  linkedin_access_token:  get('LINKEDIN_ACCESS_TOKEN','linkedin_access_token'),
  spotify_access_token:   get('SPOTIFY_ACCESS_TOKEN','spotify_access_token'),
  youtube_api_key:        get('YOUTUBE_API_KEY','youtube_api_key'),
  line_notify_token:      get('LINE_NOTIFY_TOKEN','line_notify_token'),
  google_maps_key:        get('GOOGLE_MAPS_API_KEY','google_maps_key'),
  brave_api_key:          get('BRAVE_API_KEY','brave_api_key'),
  openweathermap_key:     get('OPENWEATHERMAP_API_KEY','openweathermap_key'),
  fal_api_key:            get('FAL_API_KEY','fal_api_key'),
  elevenlabs_api_key:     get('ELEVENLABS_API_KEY','elevenlabs_api_key'),
  elevenlabs_voice_id:    get('ELEVENLABS_VOICE_ID','elevenlabs_voice_id'),
  unsplash_access_key:    get('UNSPLASH_ACCESS_KEY','unsplash_access_key'),
  nutritionix_app_id:     get('NUTRITIONIX_APP_ID','nutritionix_app_id'),
  nutritionix_api_key:    get('NUTRITIONIX_API_KEY','nutritionix_api_key'),
  finnhub_api_key:        get('FINNHUB_API_KEY','finnhub_api_key'),
  ha_url:                 get('HOME_ASSISTANT_URL','ha_url'),
  ha_token:               get('HOME_ASSISTANT_TOKEN','ha_token'),
  sonos_api_url:          get('SONOS_HTTP_API_URL','sonos_api_url'),
  lastfm_api_key:         get('LASTFM_API_KEY','lastfm_api_key'),
  lastfm_username:        get('LASTFM_USERNAME','lastfm_username'),
  lastfm_session_key:     get('LASTFM_SESSION_KEY','lastfm_session_key'),
  internal_auth_token:    get('INTERNAL_AUTH_TOKEN','internal_auth_token'),
  n8n_base_url:           get('N8N_BASE_URL','n8n_base_url'),
  database_url:           prev.databaseUrl || get('DATABASE_URL','database_url'),
  github_token:           get('GITHUB_TOKEN','github_token')
};

const userOrKey  = t.openrouter_access_token || '';
const sysOrKey   = process.env.OPENROUTER_API_KEY || '';
const PAID_MODEL = 'google/gemini-2.0-flash-001';
const FREE_MODEL = 'meta-llama/llama-3.3-70b-instruct:free';

const stage = p.ethical_profile?.growth_stage || 2;
const GROWTH_GUIDANCE = {
  1: 'User is new to research — explain clearly, avoid technical jargon, provide context',
  2: 'User is developing — guide through sources, explain tradeoffs between results',
  3: 'User is growing — synthesize multiple perspectives, encourage critical evaluation',
  4: 'User is advanced — peer-level discussion, discuss methodology and source quality',
  5: 'User is expert — focus on nuance, emerging research, and contrarian perspectives'
}[stage] || '';

const connected = Object.entries(creds).filter(([k,v]) => v).map(([k]) => k);

console.log('[Load Credentials v5 Explorer]', {
  userId: prev.userId?.substring(0,8)+'...', connected: connected.length, lang,
  hasUserKey: !!userOrKey, growthStage: stage
});

return {
  json: {
    ...prev,
    credentials: creds,
    lang, i18n,
    GROWTH_GUIDANCE, stage,
    userOrKey, sysOrKey,
    PAID_MODEL, FREE_MODEL,
    _connected: connected,
    _persona: p
  }
};

// Build Agent Context v2 — Long-Life Memory
const payload = $input.first().json;
const persona = payload._persona || payload.persona || {};
const userId = payload.userId;

const relevantMemories    = persona.relevant_memories     || [];
const keyFacts            = persona.key_facts             || [];
const ethicalProfile      = persona.ethical_profile       || {};
const interests           = persona.interests             || [];
const preferences         = persona.preferences           || {};
const relationshipFacts   = persona.relationship_facts    || [];
const goalsAndAspirations = persona.goals_and_aspirations || [];
const physicalStats       = persona.physical_stats        || {};

function buildUserContext(p) {
  const lines = [];
  lines.push(`👤 USER PROFILE`);
  lines.push(`Name: ${p.name || 'Unknown'}`);
  lines.push(`Language: ${p.language_preference || 'th'}`);
  lines.push(`Tier: ${p.subscriptionTier || 'FREE'}`);
  lines.push(`Timezone: ${p.timezone || 'Asia/Bangkok'}`);

  const hasStats = Object.values(physicalStats).some(v => v != null);
  if (hasStats) {
    const s = physicalStats;
    const parts = [];
    if (s.age)       parts.push(`age ${s.age}`);
    if (s.gender)    parts.push(s.gender);
    if (s.weight_kg) parts.push(`${s.weight_kg}kg`);
    if (s.height_cm) parts.push(`${s.height_cm}cm`);
    if (parts.length) lines.push(`Physical: ${parts.join(', ')}`);
  }

  if (p.personality_notes) lines.push(`Personality: ${p.personality_notes}`);

  if (keyFacts.length > 0) {
    lines.push(`\n📌 KEY FACTS (remember these always):`);
    keyFacts.slice(0, 8).forEach(f => lines.push(`  • ${f}`));
  }

  if (interests.length > 0) {
    lines.push(`\n💡 INTERESTS: ${interests.slice(0, 6).join(', ')}`);
  }

  if (Object.keys(preferences).length > 0) {
    const prefStr = Object.entries(preferences).slice(0, 4).map(([k,v]) => `${k}: ${v}`).join(', ');
    lines.push(`⚙️  PREFERENCES: ${prefStr}`);
  }

  if (relationshipFacts.length > 0) {
    lines.push(`\n❤️  RELATIONSHIPS:`);
    relationshipFacts.slice(0, 3).forEach(r => lines.push(`  • ${r}`));
  }

  if (goalsAndAspirations.length > 0) {
    lines.push(`\n🎯 GOALS & ASPIRATIONS:`);
    goalsAndAspirations.slice(0, 4).forEach(g => lines.push(`  • ${g}`));
  }

  if (ethicalProfile.growth_stage) {
    lines.push(`\n🌱 GROWTH: Stage ${ethicalProfile.growth_stage}/5 (${ethicalProfile.growth_stage_label || ''})`);
    if (ethicalProfile.top_strengths?.length) {
      lines.push(`   Strengths: ${ethicalProfile.top_strengths.join(', ')}`);
    }
  }

  if (relevantMemories.length > 0) {
    lines.push(`\n🧠 RELEVANT MEMORIES (from past conversations):`);
    relevantMemories.forEach((m, i) => {
      const sim = m.similarity ? ` [${(m.similarity*100).toFixed(0)}% match]` : '';
      lines.push(`  ${i+1}. [${m.type}]${sim} ${m.summary}`);
      if (m.insight) lines.push(`     → ${m.insight}`);
    });
  }

  return lines.join('\n');
}

const userContext = buildUserContext(persona);
console.log(`[BuildAgentContext] userId=${userId?.slice(0,8)}... | facts=${keyFacts.length} | memories=${relevantMemories.length} | goals=${goalsAndAspirations.length} | relationships=${relationshipFacts.length}`);

return {
  json: {
    ...payload,
    USER_CONTEXT: userContext,
    _context_built: true,
    _facts_count: keyFacts.length,
    _memories_count: relevantMemories.length
  }
};

const input = JSON.parse($input.first().json.query || '{}');
const query = input.query || input.q || '';
const limit = input.limit || 3;
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const userId = ctx.userId;
const dbUrl  = creds.database_url || process.env.DATABASE_URL || '';
const persona = ctx._persona || ctx.persona || {};
const tokens  = persona.tokens || {};
const embedKey = tokens.openrouter_access_token || process.env.OPENROUTER_API_KEY || '';

if (!dbUrl)   return { json: { error: `Database ${i18n.not_connected||'not connected'}`, memories: [] } };
if (!query || query.length < 3) return { json: { error: i18n.query_required || 'Query too short', memories: [] } };
if (!embedKey) return { json: { error: 'OpenRouter key not configured', memories: [] } };

try {
  const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${embedKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'openai/text-embedding-3-small', input: query })
  });
  if (!embedRes.ok) return { json: { error: `Embed failed: ${embedRes.status}`, memories: [] } };
  const embedData = await embedRes.json();
  const embedding = embedData.data?.[0]?.embedding;
  if (!embedding) return { json: { error: 'No embedding returned', memories: [] } };

  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const vectorStr = `[${embedding.join(',')}]`;
  const result = await pool.query(
    `SELECT content, metadata, created_at,
            1 - (embedding <=> $1::vector) AS similarity
     FROM user_data_schema.memory_embeddings
     WHERE user_id = $2 AND embedding IS NOT NULL
       AND 1 - (embedding <=> $1::vector) > 0.6
     ORDER BY embedding <=> $1::vector LIMIT $3`,
    [vectorStr, userId, limit]
  );
  await pool.end();
  const memories = result.rows.map(r => ({
    content: r.content,
    similarity: parseFloat(r.similarity.toFixed(3)),
    metadata: r.metadata || {},
    date: new Date(r.created_at).toLocaleDateString('th-TH')
  }));
  if (memories.length === 0) return { json: { message: 'No relevant memories found', memories: [], query } };
  return { json: { memories, count: memories.length, query } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}`, memories: [] } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx   = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n || {};
const searchType = (input.search_type || 'brave_search').toLowerCase();

try {
  if (searchType === 'brave_search') {
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    const braveKey = creds.brave_api_key || process.env.BRAVE_API_KEY || '';
    if (!braveKey) return { json: { error: `Brave API key ${i18n.not_connected}`, help: i18n.configure } };
    const count = input.count || 8;
    const res = await fetch(
      `https://api.search.brave.com/res/v1/web/search?q=${encodeURIComponent(input.query)}&count=${count}&country=th`,
      { headers: { 'Accept': 'application/json', 'X-Subscription-Token': braveKey } }
    );
    if (!res.ok) throw new Error(`Brave API HTTP ${res.status}`);
    const data = await res.json();
    const results = (data.web?.results || []).map(r => ({ title: r.title, url: r.url, snippet: r.description?.slice(0, 300) }));
    return { json: { query: input.query, results, count: results.length, engine: 'Brave' } };
  }
  if (searchType === 'wikipedia') {
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    const wikiLangMap = { th: 'th', en: 'en', ja: 'ja', zh: 'zh' };
    const wikiLang = wikiLangMap[input.lang || ctx.lang || 'th'] || 'en';
    const title = encodeURIComponent(input.query.replace(/ /g, '_'));
    const res = await fetch(`https://${wikiLang}.wikipedia.org/api/rest_v1/page/summary/${title}`);
    if (res.status === 404) {
      const res2 = await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${title}`);
      if (res2.status === 404) return { json: { error: `Wikipedia: '${input.query}' not found` } };
      const data2 = await res2.json();
      return { json: { title: data2.title, summary: data2.extract, url: data2.content_urls?.desktop?.page, lang: 'en', note: 'Fallback to English' } };
    }
    const data = await res.json();
    return { json: { title: data.title, summary: data.extract, url: data.content_urls?.desktop?.page, lang: wikiLang } };
  }
  if (searchType === 'fetch_url') {
    if (!input.url) return { json: { error: i18n.url_required || 'url required' } };
    const res = await fetch(input.url, { headers: { 'User-Agent': 'JARVIS-Explorer/5.0' } });
    if (!res.ok) return { json: { error: `HTTP ${res.status}`, url: input.url } };
    const text = await res.text();
    const clean = text.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);
    return { json: { url: input.url, content: clean, length: clean.length } };
  }
  return { json: { error: `Unknown search_type: ${searchType}. Use: brave_search, wikipedia, fetch_url` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx   = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n || {};
const weatherType = (input.weather_type || 'current').toLowerCase();
const city  = input.city || ctx._persona?.location || 'Bangkok';
const owmKey = creds.openweathermap_key || process.env.OPENWEATHERMAP_API_KEY || '';

if (!owmKey) return { json: { error: `OpenWeatherMap ${i18n.not_connected}`, help: i18n.configure } };
if (!city)   return { json: { error: i18n.city_required || 'city is required' } };

const owmLangMap = { th: 'th', en: 'en', ja: 'ja', zh: 'zh_cn' };
const owmLang = owmLangMap[ctx.lang || 'th'] || 'en';
const BASE = 'https://api.openweathermap.org/data/2.5';

try {
  if (weatherType === 'current') {
    const res = await fetch(`${BASE}/weather?q=${encodeURIComponent(city)}&appid=${owmKey}&units=metric&lang=${owmLang}`);
    const d = await res.json();
    if (d.cod !== 200) return { json: { error: d.message, city } };
    return { json: { city: d.name, country: d.sys?.country, temp_c: d.main?.temp, feels_like: d.main?.feels_like, humidity_pct: d.main?.humidity, description: d.weather?.[0]?.description, wind_kph: Math.round((d.wind?.speed || 0) * 3.6), visibility_km: (d.visibility || 0) / 1000, timestamp: new Date().toISOString() }};
  }
  if (weatherType === 'forecast_5day') {
    const res = await fetch(`${BASE}/forecast?q=${encodeURIComponent(city)}&appid=${owmKey}&units=metric&lang=${owmLang}&cnt=40`);
    const d = await res.json();
    if (d.cod !== '200') return { json: { error: d.message, city } };
    const byDay = {};
    for (const item of d.list) {
      const day = item.dt_txt.split(' ')[0];
      if (!byDay[day]) byDay[day] = [];
      byDay[day].push(item);
    }
    const forecast = Object.entries(byDay).slice(0, 5).map(([date, items]) => ({
      date, temp_max: Math.round(Math.max(...items.map(i => i.main.temp_max))),
      temp_min: Math.round(Math.min(...items.map(i => i.main.temp_min))),
      description: items[Math.floor(items.length / 2)].weather[0].description,
      rain_chance: Math.round(Math.max(...items.map(i => (i.pop || 0) * 100)))
    }));
    return { json: { city: d.city?.name, forecast, days: forecast.length } };
  }
  return { json: { error: `Unknown weather_type: ${weatherType}. Use: current, forecast_5day` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx   = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n || {};
const searchType = (input.search_type || 'text_search').toLowerCase();

try {
  if (searchType === 'text_search') {
    const mapsKey = creds.google_maps_key || process.env.GOOGLE_MAPS_API_KEY || '';
    if (!mapsKey) return { json: { error: `Google Maps API key ${i18n.not_connected}`, help: i18n.configure } };
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    const lat = ctx._persona?.lat || '13.7563';
    const lng = ctx._persona?.lng || '100.5018';
    const mapsLang = ['th','en','ja','zh'].includes(ctx.lang) ? ctx.lang : 'en';
    const res = await fetch(`https://maps.googleapis.com/maps/api/place/textsearch/json?query=${encodeURIComponent(input.query)}&location=${lat},${lng}&radius=5000&language=${mapsLang}&key=${mapsKey}`);
    const data = await res.json();
    if (data.status !== 'OK' && data.status !== 'ZERO_RESULTS') return { json: { error: data.status, message: data.error_message } };
    const places = (data.results || []).slice(0, 5).map(p => ({ name: p.name, address: p.formatted_address, rating: p.rating, open_now: p.opening_hours?.open_now, place_id: p.place_id }));
    return { json: { query: input.query, places, count: places.length } };
  }
  if (searchType === 'nearby') {
    const mapsKey = creds.google_maps_key || process.env.GOOGLE_MAPS_API_KEY || '';
    if (!mapsKey) return { json: { error: `Google Maps API key ${i18n.not_connected}`, help: i18n.configure } };
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    const lat = input.lat || ctx._persona?.lat || 13.7563;
    const lng = input.lng || ctx._persona?.lng || 100.5018;
    const radius = input.radius || 1000;
    const mapsLang = ['th','en','ja','zh'].includes(ctx.lang) ? ctx.lang : 'en';
    const res = await fetch(`https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=${lat},${lng}&radius=${radius}&keyword=${encodeURIComponent(input.query)}&language=${mapsLang}&key=${mapsKey}`);
    const data = await res.json();
    const places = (data.results || []).slice(0, 5).map(p => ({ name: p.name, vicinity: p.vicinity, rating: p.rating, open_now: p.opening_hours?.open_now }));
    return { json: { query: input.query, places, count: places.length, radius_m: radius } };
  }
  if (searchType === 'youtube') {
    const ytKey = creds.youtube_api_key || process.env.YOUTUBE_API_KEY || '';
    if (!ytKey) return { json: { error: `YouTube API key ${i18n.not_connected}`, help: i18n.configure } };
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    const maxResults = input.max_results || 5;
    const res = await fetch(`https://www.googleapis.com/youtube/v3/search?part=snippet&q=${encodeURIComponent(input.query)}&maxResults=${maxResults}&type=video&key=${ytKey}`);
    const data = await res.json();
    if (data.error) return { json: { error: data.error.message } };
    const videos = (data.items || []).map(v => ({ title: v.snippet.title, channel: v.snippet.channelTitle, description: v.snippet.description?.slice(0, 150), url: `https://youtube.com/watch?v=${v.id.videoId}`, published: v.snippet.publishedAt }));
    return { json: { query: input.query, videos, count: videos.length } };
  }
  return { json: { error: `Unknown search_type: ${searchType}. Use: text_search, nearby, youtube` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx   = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n  = ctx.i18n || {};
const toolType = (input.tool_type || 'github_search').toLowerCase();
const ghToken = creds.github_token || process.env.GITHUB_TOKEN || '';
const ghHeaders = { 'Accept': 'application/vnd.github.v3+json', 'User-Agent': 'JARVIS-Explorer/5.0', ...(ghToken ? { 'Authorization': `Bearer ${ghToken}` } : {}) };

try {
  if (toolType === 'github_repos') {
    const username = ctx._persona?.github_username || input.username || '';
    if (!username) return { json: { error: i18n.github_username_missing || 'github_username not set in persona' } };
    const res = await fetch(`https://api.github.com/users/${username}/repos?sort=updated&per_page=15`, { headers: ghHeaders });
    const data = await res.json();
    if (!Array.isArray(data)) return { json: { error: data.message || `GitHub API ${i18n.error}` } };
    return { json: { repos: data.map(r => ({ name: r.name, description: r.description, stars: r.stargazers_count, language: r.language, updated: r.updated_at?.split('T')[0], url: r.html_url })), count: data.length }};
  }
  if (toolType === 'github_issues') {
    if (!input.repo) return { json: { error: i18n.repo_required || 'repo required (e.g. user/repo)' } };
    const state = input.state || 'open';
    const res = await fetch(`https://api.github.com/repos/${input.repo}/issues?state=${state}&per_page=15`, { headers: ghHeaders });
    const data = await res.json();
    if (!Array.isArray(data)) return { json: { error: data.message || `GitHub API ${i18n.error}` } };
    const issues = data.filter(i => !i.pull_request).map(i => ({ number: i.number, title: i.title, state: i.state, created: i.created_at?.split('T')[0], url: i.html_url }));
    return { json: { repo: input.repo, issues, count: issues.length }};
  }
  if (toolType === 'github_search') {
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    const type = input.type || 'repos';
    const endpoint = type === 'code' ? 'code' : type === 'users' ? 'users' : 'repositories';
    const res = await fetch(`https://api.github.com/search/${endpoint}?q=${encodeURIComponent(input.query)}&sort=stars&per_page=8`, { headers: ghHeaders });
    if (!res.ok) throw new Error(`GitHub API HTTP ${res.status}`);
    const data = await res.json();
    if (type === 'repos') {
      return { json: { results: (data.items || []).map(r => ({ name: r.full_name, description: r.description?.slice(0, 200), stars: r.stargazers_count, language: r.language, url: r.html_url, updated: r.updated_at?.split('T')[0] })), total: data.total_count }};
    }
    return { json: { results: (data.items || []).slice(0, 8), total: data.total_count, type }};
  }
  if (toolType === 'npm_search') {
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    const res = await fetch(`https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(input.query)}&size=5`);
    const data = await res.json();
    return { json: { packages: (data.objects || []).map(o => ({ name: o.package.name, version: o.package.version, description: o.package.description, weekly_downloads: o.downloads?.weekly, url: `https://npmjs.com/package/${o.package.name}` })), count: data.objects?.length || 0 }};
  }
  if (toolType === 'pypi_info') {
    if (!input.package) return { json: { error: i18n.package_required || 'package name required' } };
    const res = await fetch(`https://pypi.org/pypi/${input.package}/json`);
    if (res.status === 404) return { json: { error: `Package '${input.package}' not found on PyPI` } };
    const data = await res.json();
    const info = data.info;
    return { json: { name: info.name, version: info.version, summary: info.summary, author: info.author, license: info.license, home_page: info.home_page, requires_python: info.requires_python }};
  }
  if (toolType === 'http_test') {
    if (!input.url) return { json: { error: i18n.url_required || 'url required' } };
    const method = (input.method || 'GET').toUpperCase();
    const startTime = Date.now();
    const res = await fetch(input.url, { method, headers: { 'User-Agent': 'JARVIS-Explorer/5.0', ...(input.headers || {}) }, body: input.body ? JSON.stringify(input.body) : undefined });
    const duration = Date.now() - startTime;
    const text = await res.text();
    let body;
    try { body = JSON.parse(text); } catch { body = text.slice(0, 500); }
    return { json: { url: input.url, method, status: res.status, ok: res.ok, duration_ms: duration, response: body }};
  }
  return { json: { error: `Unknown tool_type: ${toolType}. Use: github_repos, github_issues, github_search, npm_search, pypi_info, http_test` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input   = JSON.parse($input.first().json.query || '{}');
const ctx     = $('Load Credentials').first().json;
const creds   = ctx.credentials || {};
const i18n    = ctx.i18n || {};
const userId  = ctx.userId;

if (!input.query) return { json: { error: i18n.query_required || 'query required' } };

const dbUrl    = creds.database_url || process.env.DATABASE_URL || '';
const persona  = ctx._persona || ctx.persona || {};
const tokens   = persona.tokens || {};
const embedKey = tokens.openrouter_access_token || process.env.OPENROUTER_API_KEY || '';

if (!dbUrl) return { json: { error: `Database ${i18n.not_connected || 'not connected'}`, results: [] } };

try {
  if (embedKey) {
    const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${embedKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'openai/text-embedding-3-small', input: input.query })
    });
    if (embedRes.ok) {
      const embedData = await embedRes.json();
      const embedding = embedData.data?.[0]?.embedding;
      if (embedding && Array.isArray(embedding)) {
        const { Pool } = require('pg');
        const pool = new Pool({ connectionString: dbUrl });
        const vectorStr = `[${embedding.join(',')}]`;
        const result = await pool.query(
          `SELECT content, metadata, 1 - (embedding <=> $1::vector) AS similarity FROM user_data_schema.knowledge_base WHERE user_id = $2 AND embedding IS NOT NULL AND 1 - (embedding <=> $1::vector) > 0.5 ORDER BY embedding <=> $1::vector LIMIT 5`,
          [vectorStr, userId]
        );
        await pool.end();
        return { json: { results: result.rows || [], count: result.rows.length, mode: 'vector' } };
      }
    }
  }
  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const result = await pool.query(
    `SELECT content, metadata FROM user_data_schema.knowledge_base WHERE user_id = $1 AND content ILIKE $2 LIMIT 5`,
    [userId, `%${input.query}%`]
  );
  await pool.end();
  return { json: { results: result.rows || [], count: result.rows.length, mode: 'keyword_fallback' } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}`, results: [] } };
}

const raw  = $input.first().json;
const out  = raw.output || raw.agentOutput || raw.text || raw.message || 'ไม่พบข้อมูล';
const prev = $('Extract Payload').item.json;
return { json: { ...prev, message: out, response: out, output: out, agentOutput: out, agentCategory: 'explorer', processedAt: new Date().toISOString(), _llm_tier: raw._llm_tier || 'langchain' } };
